```cpp
template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    constexpr int VEC = 8;
    int n_vec = hidden_size / VEC;

    // Step 1: compute sum of squares using vectorized loads
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < n_vec; i += blockDim.x) {
        float4 vx = *reinterpret_cast<const float4*>(x + i * VEC);
        const scalar_t* svx = reinterpret_cast<const scalar_t*>(&vx);
        #pragma unroll
        for (int j = 0; j < VEC; j++) {
            float val = static_cast<float>(svx[j]);
            sum_sq += val * val;
        }
    }
    for (int i = threadIdx.x + n_vec * VEC; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
    }

    // Warp-level reduction
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (blockDim.x + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (threadIdx.x == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    // Step 2: normalize and scale using vectorized loads/stores
    for (int i = threadIdx.x; i < n_vec; i += blockDim.x) {
        float4 vx = *reinterpret_cast<const float4*>(x + i * VEC);
        float4 vw = *reinterpret_cast<const float4*>(weight + i * VEC);
        const scalar_t* svx = reinterpret_cast<const scalar_t*>(&vx);
        const scalar_t* svw = reinterpret_cast<const scalar_t*>(&vw);
        float4 vo;
        scalar_t* svo = reinterpret_cast<scalar_t*>(&vo);
        #pragma unroll
        for (int j = 0; j < VEC; j++) {
            float val = static_cast<float>(svx[j]);
            float w = static_cast<float>(svw[j]);
            svo[j] = static_cast<scalar_t>(val * rms_inv * w);
        }
        *reinterpret_cast<float4*>(o + i * VEC) = vo;
    }
    for (int i = threadIdx.x + n_vec * VEC; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        float w = static_cast<float>(__ldg(&weight[i]));
        o[i] = static_cast<scalar_t>(val * rms_inv * w);
    }
}
```

